describe('Screen Reader Error Message Announcements', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should announce form validation errors to screen readers', () => {
    cy.get('input[name="email"]').focus().blur();

    cy.get('[role="alert"]')
      .should('be.visible')
      .should('have.attr', 'aria-live', 'polite')
      .should('contain', 'Email is required');

    cy.get('[role="alert"]').should('have.attr', 'aria-atomic', 'true');
  });

  it('should announce multiple errors with proper ARIA attributes', () => {
    cy.get('input[name="password"]').focus().blur();
    cy.get('input[name="confirmPassword"]').focus().blur();

    cy.get('[role="alert"]').should('have.length.greaterThan', 1);

    cy.get('[role="alert"]').each(($alert) => {
      cy.wrap($alert)
        .should('have.attr', 'aria-live')
        .and('match', /polite|assertive/);

      cy.wrap($alert)
        .should('have.attr', 'aria-atomic', 'true');
    });
  });

  it('should update error message dynamically and announce changes', () => {
    cy.get('input[name="email"]').type('invalid-email');
    cy.get('button[type="submit"]').click();

    cy.get('[role="alert"]')
      .should('contain', 'Invalid email format');

    cy.get('input[name="email"]').clear().type('valid@example.com');

    cy.get('[role="alert"]')
      .should('not.exist');
  });

  it('should associate error messages with form fields using aria-describedby', () => {
    cy.get('input[name="username"]').should('have.attr', 'aria-describedby');

    const describedById = cy.get('input[name="username"]').invoke('attr', 'aria-describedby');

    cy.get('input[name="username"]').focus().blur();

    describedById.then((id) => {
      cy.get(`#${id}`)
        .should('be.visible')
        .should('have.attr', 'role', 'alert')
        .should('contain.text', 'Username is required');
    });
  });

  it('should handle error announcements with aria-label for screen readers', () => {
    cy.get('input[name="age"]').type('-5');
    cy.get('button[type="submit"]').click();

    cy.get('[role="alert"]')
      .should('have.attr', 'aria-label')
      .and('contain', 'Error');

    cy.get('[role="alert"]').should('contain', 'Age must be a positive number');
  });

  it('should announce field-level errors with proper semantic HTML', () => {
    cy.get('form').within(() => {
      cy.get('input[name="phone"]').focus().blur();

      cy.get('input[name="phone"]')
        .parent()
        .find('[role="alert"]')
        .should('exist')
        .should('have.attr', 'aria-live', 'polite');
    });
  });

  it('should clear error announcements when field is corrected', () => {
    cy.get('input[name="email"]').focus().blur();
    cy.get('[role="alert"]').should('be.visible');

    cy.get('input[name="email"]').type('correct@example.com');
    cy.get('[role="alert"]').should('not.exist');
  });
});
